//		Exec(ctx)
func (_c *EndpointACLCreateBulk) OnConflictColumns(columns ...string) *EndpointACLUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &EndpointACLUpsertBulk{
		create: _c,
	}
}

